#pragma once

#include "base.hpp"

namespace epi::presets {

/**
 * Escher-Lenstra-de Smit "Print Gallery" Conformal Droste Riemann Surface.
 *
 * Mathematical foundation:
 * - Bart de Smit & Hendrik W. Lenstra Jr. (2003, Notices of the AMS 50(4),
 *   "The Mathematical Structure of Escher's Print Gallery"): Escher's 1956
 *   lithograph of a gallery containing itself lives on the elliptic curve /
 *   complex torus C / Lambda generated by the Droste multiplier:
 *     alpha = (ln(256) + 2*pi*i) / (2*pi*i) = 1 - i * ln(256)/(2*pi)
 *           = 1 - 0.882542401 i   (|alpha| = 1.33375, tilt = -41.4296 deg).
 *   Exponentiating this tilted lattice closes the scale-256 dilation into a
 *   single seamless spiral sheet with zero central singularity!
 *
 * Mapping to the 6-stage OpenCL / Vulkan pipeline:
 * - Inner = Exp + Grid wrap with zn[0] anchored directly on the Lenstra-de Smit
 *   complex period (1.334, -1.177) so every recursive feedback generation wraps
 *   around the Droste monodromy spiral!
 * - Color = DepthEcho (mode 5): preserves multi-octave recursive frame strata.
 */
inline Pattern op_art_escher_droste_riemann_gallery() {
  Pattern p;
  p.name = "op_art_escher_droste_riemann_gallery";
  p.inner = InnerFunction::Exp;
  p.reduction = ReductionType::Grid;

  // Scaled Lenstra-de Smit complex period ratio (1 : -0.8825424)
  p.zn.zn[0] = {1.340f, -1.182f};
  p.zn.zn[1] = {0.055f, 0.042f};
  p.zn.zn[2] = {1.060f, 0.140f};
  p.zn.zn[3] = {-0.025f, 0.018f};

  p.zn.zn0_animate = true;
  p.zn.zn0_anim_speed = 0.076f;
  p.zn.zn0_anim_amp = 0.042f;
  p.zn.zn1_animate = true;
  p.zn.zn1_anim_speed = 0.098f;
  p.zn.zn1_anim_amp = 0.055f;
  p.zn.zn1_anim_k = 4.0f;

  p.color.hue_rotation = 0.014f;
  p.color.sat_scale = 1.08f;
  p.color.fade = 0.987f;
  p.color.color_mode = as_int(ColorMode::DepthEcho);
  p.color.spiral_angle_coeff = 2.0f;
  p.color.spiral_radius_coeff = 0.8825f;
  p.color.chroma_breath_amp = 0.25f;
  p.color.chroma_breath_freq = 0.15f;
  p.color.chroma_breath_phase = 0.0f;
  p.color.hue_velocity_base = 0.022f;
  p.color.hue_velocity_breath = 0.014f;
  p.color.hue_velocity_drift = 0.006f;
  p.color.luma_shape_depth = 0.22f;
  p.color.luma_shape_center = -4.22f;

  p.seed.type = SeedType::Simplex;
  p.seed.border_width = 0.075f;
  p.seed.hue = 0.62f;
  p.seed.hue_speed = 0.11f;
  p.seed.alpha = 0.92f;
  p.seed.pulse_freq = 0.09f;
  p.seed.pulse_amp = 0.17f;

  p.speed = 0.86f;

  p.motion
      .add("droste_monodromy_twist",
           control::ModLane{.wave = control::Waveform::Sine,
                            .frequency_hz = 0.064f,
                            .amplitude = 0.085f,
                            .offset = 0.140f},
           control::ModTarget::Zn2Im)
      .add("riemann_sheet_pitch",
           control::ModLane{.wave = control::Waveform::Sine,
                            .frequency_hz = 0.049f,
                            .amplitude = 0.24f,
                            .offset = 0.8825f,
                            .phase = 0.25f},
           control::ModTarget::SpiralRadiusCoeff)
      .add("echo_strata_breath",
           control::ModLane{.wave = control::Waveform::Triangle,
                            .frequency_hz = 0.083f,
                            .amplitude = 0.08f,
                            .offset = 0.25f},
           control::ModTarget::ChromaBreathAmp)
      .add("gallery_hue_precession",
           control::ModLane{.wave = control::Waveform::Sine,
                            .frequency_hz = 0.039f,
                            .amplitude = 0.008f,
                            .offset = 0.014f},
           control::ModTarget::HueRot);

  return p;
}

} // namespace epi::presets
